items=[]
def m(s):return r'\('+s+r'\)'
def add(q,stem,values,reasons,ans,solution,core,concept,labels,cites,discipline='basic_2_1',conditions=None,calc=False,fig=False,direction='最も不適切',verdicts=None,figure_note='設問固有図なし。'):
 r=by[q];assert len(values)==len(reasons)==5
 if verdicts is None:verdicts=[('不適切' if direction=='最も不適切' else '適切') if i==ans else ('適切' if direction=='最も不適切' else '不適切') for i in range(1,6)]
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions or {'方向':direction},choices={str(i):dict(value=v,verdict=j,reason=w) for i,(v,j,w) in enumerate(zip(values,verdicts,reasons),1)},figures='問題幹・全5肢・数値・単位・否定を原典画像照合。'+figure_note,ambiguity='',evidence=ini[q]['source_images_viewed'],core_concept=core,required_knowledge=core+'。'+solution,solution=solution,independent_answer=ini[q]['independent_answer'],answer_reason=solution,learning_points='符号化の目的、情報量と物理的データ長、条件付き時間と平均時間を区別する。'+core+'の定義と適用条件を確認する。',theory_references=['theory:information:'+s for s in labels],discipline_id=discipline,concept_id=concept,classification_reason='原典の数式・図表・全肢から中心課題を確定。'+core+'を中心とする。索引用の旧自動分類と異なるときは本文の実際の課題を優先する。',calculation=str(calc).lower(),figure=str(fig).lower(),law='false',evaluation=dict(knowledge_novelty='2',reasoning_steps='2',calculation_load='1' if calc else '0',figure_reading='1' if fig else '0',difficulty='2',difficulty_reason='物理専攻者には情報工学の名称が新しいが、剰余・線形代数・期待値・次元換算による一〜二段の判断である。'),citations=cites,foundationality='high',transferability='high'))
mv=['晴→2日後雨5/16','曇→2日後曇3/8','雨→2日後曇5/16','雨→2日後雨1/4','初日雨から遠い将来の雨確率1/3']
mr=['晴→晴→雨、晴→曇→雨、晴→雨→雨の排他的3経路を足すと1/8+1/16+1/8=5/16。','曇→曇→曇、曇→雨→曇、曇→晴→曇を足すと1/4+1/16+1/16=3/8。','自己遷移を一方の時刻に含む2経路と、晴を経る経路で5/16。','自己遷移を2回行う経路だけなら1/4だが、他の2状態を経て戻る1/16ずつを忘れている。合計3/8。','全ての1日遷移が正で、対称な行列の定常分布は一様。有限既約・非周期の連鎖でこの分布へ収束する。']
sol='状態を晴・曇・雨と並べると遷移行列は対角1/2、非対角1/4である。2日後は'+m(r'(P^2)_{ij}=\sum_kP_{ik}P_{kj}')+'から自己3/8、異なる状態5/16。定常分布は(1/3,1/3,1/3)であり、全要素正のため初期天気によらず収束する。'
add('H24-REG-BASIC-2-3','3状態の天気遷移図から2日後の条件付き確率と長期極限を判定する。',mv,mr,4,sol+'肢4の1/4が誤りである。','有限マルコフ連鎖の経路和・行列累乗・定常分布','markov_transition',['markov'],['info_markov'],calc=True,fig=True,figure_note='3頂点の自己ループ1/2、6本の他状態への矢印1/4を画像確認。')
add('H28-REG-BASIC-2-1','同じ3状態の天気遷移図で、2日後確率の異なる記述を検証する。',['雨→雨3/8',mv[0],mv[1],'曇→晴3/16',mv[4]],['雨→雨→雨1/4、雨→曇→雨1/16、雨→晴→雨1/16の合計3/8。',mr[0],mr[1],'曇→曇→晴1/8、曇→雨→晴1/16、曇→晴→晴1/8の和は5/16。3/16ではない。',mr[4]],4,sol+'肢4の曇→晴3/16が不適切である。','有限マルコフ連鎖の経路和・行列累乗・定常分布','markov_transition',['markov'],['info_markov'],calc=True,fig=True,figure_note='自己3本1/2と他6本1/4を両年度で別々に照合。')
add('H24-REG-BASIC-2-4','2バイト文字の新聞を半分に圧縮したとき、指定容量へ格納できる頁数を求める。',['約1万頁','約4万頁','約8万頁','約16万頁','約32万頁'],['約81920頁に対して約8分の1であり、ビットとバイトの8倍を誤って適用した規模である。','圧縮後は1頁10240バイト。圧縮を無視すると40960頁だが指定条件に反する。','800×1024²/10240=81920頁で、この候補が最近。','81920頁の約2倍で、文字の2バイトと50%圧縮を二重に消している。','81920頁の約4倍で、与えられた容量/1頁容量の比とは合わない。'],3,'圧縮前1頁は10240×2=20480バイト、圧縮後は10240バイト。Mは明示的に1024²なので全容量は838860800バイト。割ると81920頁となり3が最近。現行SIのM=10^6や実際の文字コードの可変幅を、この問題の指定へ持ち込まない。','指定単位と圧縮後データ長による容量計算','data_transfer',['transfer'],['info_deflate'],calc=True,direction='最も近い値',conditions={'文字数/頁':'10240','文字幅':'2バイト','圧縮後/前':'0.5','容量':'800Mバイト、M=1024²'})
add('H26-REG-BASIC-2-3','ISBN-10の重み付き剰余条件を保つ数字の変更を選ぶ。',['第2桁0→5：95-70002-34-5','第8桁3→8：90-70002-84-5','検査数字5→6：90-70002-34-6','第8/9桁34→82：90-70002-82-5','第8/9桁34→56：90-70002-56-5'],['第2桁の重み9、差5で和が45増える。元和176に足した221は11の倍数でない。','重み3の桁が5増えるので和が15増える。191は11の倍数でない。OCRの04は画像の84へ校正する。','検査桁の重み1で和が177となり、余り1なので無効。','重み3と2の変化は3×5+2×(-2)=11。全和187=17×11となり有効。','変化は3×2+2×2=10。186は余り10で無効。'],4,'先頭9桁の和171に検査数字5を加えると176=16×11。変更後の全和を毎回計算するより、変更差が11の倍数か判定するとよい。候補差は45,15,1,11,10で、4だけ有効。これは検査数字規則に適合するという意味であり、番号が実際に出版物へ割り当て済みという保証ではない。','重み付き検査数字と剰余による誤り検出','information_codes',['checksum'],['info_errors'],calc=True,fig=True,direction='正しい番号',figure_note='ISBN数字9,0,7,0,0,0,2,3,4、重み10〜2、積171と全5変更を画像確認。')
add('R05-REG-BASIC-2-3','ISBN-13の交互重み1/3の合同式から欠けた末尾検査数字を求める。',['1','3','5','7','9'],['101+1=102はmod10で2。','101+3=104はmod10で4。','101+5=106はmod10で6。','101+7=108はmod10で8。','101+9=110はmod10で0となる。'],5,'原典の番号は978-4-103-34194-Xで、Xは末尾桁である。左から1/3交互の重みを掛けると9+21+8+12+1+0+3+9+4+3+9+12=101。'+m(r'101+X\equiv0\pmod{10}')+'を満たす0〜9は9であり5が適切。ISBN-10の重み10〜1、法11とは異なる規則である。','ISBN-13の検査数字と交互重みの合同式','information_codes',['checksum'],['info_isbn'],calc=True,direction='適切な数値',conditions={'番号':'978-4-103-34194-X','左から重み':'1,3交互','合同式':'全和mod10=0'})
pv=['1ビット反転検出には元データ8ビット以下が必要。','1ビット反転検出には元データ2ビット以上が必要。','8ビットデータの1ビット反転位置が特定できる。','2ビット反転では誤りを検出できない。','データによって付加ビットを決められない。']
pr=['長さに関係なく1回の反転で全体の1の個数の偶奇が変わる。8ビットという上限はない。','1ビットのデータにも付加でき、反転は検出できる。2ビットという下限はない。','受信全体の偶奇だけでは、データ中の各位置やパリティ位置のどれが変わったか区別できない。','異なる2ビットの反転は偶奇を2回反転するため元の偶数に戻る。検査値0でも元データ一致の保証はない。','任意の有限ビット列で1の個数は偶数か奇数のいずれかなので、一意に付加値が決まる。']
for q,order,ans in [('H28-REG-BASIC-2-5',[0,1,2,3,4],4),('R06-REG-BASIC-2-4',[0,1,2,4,3],5)]:
 add(q,'偶数パリティ1ビットの付加による検出能力と、位置特定の可否を判断する。',[pv[i] for i in order],[pr[i] for i in order],ans,'パリティを'+m(r'b=\sum_ix_i\pmod2')+'と置くと、データとbの全和は偶数になる。誤りベクトルeを足した受信列の検査値は'+m(r'\sum_ie_i\pmod2')+'であり、奇数個反転だけ検出できる。異なる2ビット反転は検出不能で、単一検査値から反転位置も決まらない。元1010100の1は3個、付加1で10101001の1が4個になることも画像確認した。','偶数パリティの検出条件と訂正能力の区別','information_codes',['parity'],['info_errors'],direction='最も適切',conditions={'元データ例':'1010100','付加ビット':'1の個数偶数なら0、奇数なら1','送信列例':'10101001'})
add('R01-REG-BASIC-2-4','形式文法で生成できる数値列を、符号と整数部分の規則から判断する。',['-19.1','.52','-.37','4.35','-125'],['符号-と数字列19が整数を生成し、小数.1と結合できる。','小数点と非空数字列52で小数だけを生成できる。','符号は整数の生成規則にだけ現れ、整数には必ず数字列が要る。整数桁のない-.37は生成不能。','整数4と小数.35の結合で生成できる。','符号-と数字列125で整数を生成できる。'],3,'根の数値は整数、小数、整数小数の3通りである。整数は数字列又は符号数字列、小数は点数字列であり、数字列は1桁から再帰的に長くできる。符号は単独で小数に付かないため-.37だけ生成不能で、-0.37なら生成できる。日常の数値表記の許容ではなく、提示規則だけを使う。','生成規則における符号の所属と非空数字列','concept_021',['grammar'],[],discipline='basic_2_0',direction='最も不適切',conditions={'生成規則':'数値→整数/小数/整数小数、整数→数字列/符号数字列、小数→点数字列、数字列は非空'})
cv=['可逆圧縮は完全復元しテキスト等で多用。','非可逆圧縮は完全復元しない場合があり音声・映像等で多用。','JPEGは静止画、MPEGは動画の代表的圧縮方式。','情報源の事前知識がなければデータ圧縮できない。','可逆圧縮には方式では超えられない限界がある。']
cr=['元ビット列を一意に復元する性質が可逆の定義である。文字1つの変更が意味を変えるテキストでは重要。','知覚上許せる情報損失を利用してデータ量を減らす。全ての音声/映像が非可逆という断定ではない。','代表用途として正しい。JPEG/MPEGは複数の方式・規格を持つ名称であり、全方式を一律に可逆/非可逆とは扱わない。','データから頻度を学ぶ適応方式や繰り返しを辞書へ写す方式が反例。真の生起確率を事前に与える必要はない。','一意復号可能な符号の平均長はエントロピーで制約され、全ての入力を必ず短くする単射も作れない。個別列が必ず同じ下限長という意味ではない。']
for q,order,ans in [('R02-REG-BASIC-2-1',[0,1,2,3,4],4),('R05-REG-BASIC-2-4',[3,4,1,0,2],1)]:
 add(q,'可逆/非可逆圧縮、代表形式、未知情報源への圧縮可能性と圧縮限界を比較する。',[cv[i] for i in order],[cr[i] for i in order],ans,'事前分布の既知性と、観測データから規則を構成することを区別する。DEFLATEの反復列への参照や動的符号表は、入力から圧縮表現を作れる具体例である。未知だから圧縮不能という肢が不適切。限界は一意復号や平均長の条件付きであり、特定の短い列にエントロピー平均下限を機械的に適用しない。','可逆性・平均符号長の限界と普遍的/適応的圧縮','source_compression',['compression','entropy','universal'],['info_deflate','info_lossless','info_universal','info_jpeg','info_mpeg'])
add('H28-REG-BASIC-2-4','ヒット率95%のキャッシュと主記憶の平均アクセス時間に最近の値を求める。',['0.05ns','0.95ns','5.00ns','5.95ns','95.0ns'],['ミス率0.05という無次元数だけであり、アクセス時間になっていない。','ヒット側0.95×1だけでミス側を忘れている。','ミス側0.05×100だけでヒット側を忘れている。','ヒット/ミスの総時間を1/100nsとするモデルでは0.95+5=5.95ns。','ヒット率を遅い主記憶に掛けており条件付き時間の対応が逆。'],4,'ヒット確率hに対する期待時間は'+m(r'E[T]=hT_{\rm hit}+(1-h)T_{\rm miss}')+'である。与えられた1ns/100nsをヒット/ミス総時間とする簡略モデルで5.95nsとなる。主記憶100nsを照合後の追加時間とする逐次モデルなら1+0.05×100=6nsであり、それでも候補4が最近。どちらの式も定義を付けて使い、実装一般の厳密時間を5.95nsに固定しない。','キャッシュの条件付き時間と確率重み付き平均','concept_018',['cache'],['info_cache'],discipline='basic_2_5',calc=True,direction='最も近い値',conditions={'ヒット総時間':'1.00ns','主記憶時間':'100ns','ヒット率':'0.95'})
add('R02-REG-BASIC-2-6','キャッシュ平均時間と主記憶だけに対する速度比を組として求める。',['45ns/2倍','60ns/2倍','60ns/5倍','90ns/2倍','90ns/5倍'],['45nsはヒット側0.9×50だけで、ミス45nsが抜ける。速度比も450/90とは違う。','ヒット/ミス重み付き平均90nsとは一致せず、450/60=7.5で2倍でもない。','60nsは平均に合わず、450/60=7.5なので5倍とも整合しない。','時間90nsは簡略モデルで合うが速度比は450/90=5、2ではない。','0.9×50+0.1×450=90ns、450/90=5倍の両方が一致する。'],5,'ヒット/ミス総時間を50/450nsとする簡略モデルでは平均90ns。同じデータを呼ぶ速さは時間に反比例するので、主記憶単独450nsとの比は450/90=5である。ミス時に50ns照合後450nsを追加するモデルなら95ns・約4.74倍となり、それでも組の候補5が最も近い。主記憶時間を総時間か追加ペナルティか先に定義する。','キャッシュの平均時間と逆数としての速度比','concept_018',['cache'],['info_cache'],discipline='basic_2_5',calc=True,direction='最も適切',conditions={'キャッシュ':'50ns','主記憶':'450ns','ヒット率':'0.90'})
add('R03-REG-BASIC-2-3','圧縮後データ量と有効通信速度から伝送秒数を求める。',['286秒','143秒','100秒','18秒','13秒'],['5GBを圧縮せず計算すると約285.7秒になるが半分への圧縮を無視する。','20×10^9bit/(140×10^6bit/s)=142.857秒で最近。','利用率70%を忘れた20×10^9/(200×10^6)=100秒。','圧縮後バイト量をビット量へ8倍しないと約17.86秒になる。','利用率も8倍換算も忘れると12.5秒でこの規模になる。'],2,'圧縮後は2.5×10^9バイト=20×10^9ビット。有効速度は200×10^6×0.70=140×10^6ビット/秒。比は約142.857秒、最近は143秒の2。G/Mは原典指定の10^9/10^6であり、1024の累乗ではない。','伝送データ長と有効速度の単位換算','data_transfer',['transfer'],['info_deflate'],discipline='basic_2_3',calc=True,direction='最も近い値',conditions={'元量':'5GB、G=10^9','圧縮後/前':'0.5','回線速度':'200Mbps','利用率':'0.70'})
add('R07-REG-BASIC-2-5','既知の圧縮率、通信速度と伝送時間から回線利用率を逆算する。',['8%','10%','16%','64%','80%'],['200Mバイトをそのまま100Mbit/sと25秒で割ると0.08となり、バイト/ビット換算が抜ける。','与えられた圧縮後ビット量1.6Gbitに対し、250Mbitしか25秒で送れない値。','1.6Gbitの4分の1しか25秒で送れず、時間と整合しない。','250×10^6×0.8×8/(100×10^6×25)=0.64で整合。','圧縮前データを用いると0.80となるが、実際は0.8倍に圧縮して送る。'],4,'圧縮後は200×10^6バイト=1.6×10^9ビット。'+m(r't=D/(v\eta)')+'を'+m(r'\eta=D/(vt)')+'へ解くと1.6×10^9/(100×10^6×25)=0.64となる。比は無次元で百分率64%。0.8は圧縮率であり利用率そのものではない。','通信時間式の逆算と圧縮率/利用率の区別','data_transfer',['transfer'],['info_deflate'],discipline='basic_2_3',calc=True,direction='最も適切',conditions={'元量':'250MB、M=10^6','圧縮後/前':'0.8','回線速度':'100Mbps','時間':'25秒'})
add('R07-REG-BASIC-2-2','情報源符号化、通信路符号化、分離原理、普遍符号化、多元情報理論を区別する。',['情報源系列から通信路入力への変換が符号化、受信から元系列等への変換が復号化。','雑音なしで情報源長を固定し通信路入力長を小さくする課題が情報源符号化。','一様な無記憶情報源で通信路入力長を固定し情報源長/伝送レートを増す課題が通信路符号化。','情報源符号化で通信路の確率特性を逐一考慮しない扱いがユニバーサル符号化。','相関した複数情報源や複数通信路の圧縮/伝送を多元情報理論で扱う。'],['通信系における符号器/復号器の基本的役割を述べる。非可逆では元に近い系列へ復元する場合もある。','既定の情報を短い符号列へ表す圧縮の課題である。','固定長の通信路利用で送れるメッセージ数を増し、誤り確率を抑える通信路符号化の課題である。','標準的な情報源と通信路の分離原理の話である。普遍符号化は情報源分布などが未知なクラスに対応する概念であり、通信路特性を考慮しないという定義ではない。','複数利用者・相関情報源のモデルを扱う一般的な分野説明である。分離が多元モデルで常に最適という追加主張はない。'],4,'圧縮は情報源の冗長性を減らし、通信路符号化は雑音に耐える制御された冗長性を加える。定常無記憶な点対点モデルで十分長いブロックを使うなどの条件では両設計を分離できる。一方、普遍符号化は事前に真の情報源分布を知らない場合に対応する考えである。4はこの名称を取り違える。通信路容量との整合や有限遅延での性能まで無視できるわけではない。','情報源/通信路符号化の目的と分離/普遍性の条件','source_compression',['separation','universal','entropy'],['info_separation','info_universal','info_lossless'],conditions={'方向':'最も不適切','モデルの範囲':'単一情報源・単一入力単一出力通信路と多元系を区別'})
